def get_valid_input(prompt):
    """Get valid input from user."""
    while True:
        try:
            user_input = input(prompt)
            return user_input
        except ValueError:
            print("That's not a valid input. Please try again.")

def get_arithmetic_operation():
    """Get arithmetic operation from user."""
    while True:
        operation = input("Enter the arithmetic operation (+, -, *, /): ").upper()
        if operation in ['+', '-', '*', '/']:
            return operation
        else:
            print("That's not a valid operation. Please try again.")

def calculate(num1, num2, operation):
    """Perform arithmetic calculation."""
    if operation == '+':
        return num1 + num2
    elif operation == '-':
        return num1 - num2
    elif operation == '*':
        return num1 * num2
    elif operation == '/':
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        return num1 / num2
    else:
        raise ValueError("Invalid operation.")

if __name__ == "__main__":
    num1 = float(get_valid_input("Enter the first number: "))
    operation = get_arithmetic_operation()
    num2 = float(get_valid_input("Enter the second number: "))

    try:
        result = calculate(num1, num2, operation)
        print(f"{num1} {operation} {num2} = {result}")
    except ValueError as e:
        print(e)
